		return
	} else if r.Method == "POST" {
		// handle INSERT or UPDATE
		return
	}

	w.WriteHeader(http.StatusMethodNotAllowed)
	return
}

// Addr returns the address on which the Service is listening
func (s *Service) Addr() net.Addr {
	return s.ln.Addr()
}

