			if float64(intNum) == rawData.(float64) {
				return createScalarNode(intNum, fmt.Sprintf("%v", intNum)), nil
			}

			return createScalarNode(rawData, fmt.Sprintf("%v", rawData)), nil
		case int, int64, int32, string, bool:
