			parts[i] = gen.Type(argType)
		}
	}
	return strings.Join(parts, `, `)
}

// Type returns the filter part for a single type.
func (gen *filterGen) Type(typ types.Type) string {
	switch t := typ.(type) {
	case types.Object:
