/* TODO(chriskirkland): work left to do:
*	- validate that migrating binlog events after migration is in-flight work
* 	- validate migration waits for cutover flag (^ related)
*   - DROP target table if it exists on the cluster pre-migration
*
*   - Cleanup lots of debug/info logging
*   - lots and lots of refactoring, state isolation, dependency injection, etc. :)
 */

func (mgtr *Migrator) MoveTables() (err error) {
	mgtr.migrationContext.Log.Infof("Moving tables %v from %s to %s (%s)",
		mgtr.migrationContext.MoveTables.TableNames,
		sql.EscapeName(mgtr.migrationContext.DatabaseName),
		sql.EscapeName(mgtr.migrationContext.MoveTables.TargetDatabase), mgtr.migrationContext.MoveTables.TargetHost)
	mgtr.migrationContext.StartTime = time.Now()

	if mgtr.migrationContext.OriginalTableName == "" {
		mgtr.migrationContext.OriginalTableName = mgtr.migrationContext.MoveTables.TableNames[0]
	}

	// Ensure context is cancelled on exit (cleanup)
	defer mgtr.migrationContext.CancelContext()

	if mgtr.migrationContext.Hostname, err = os.Hostname(); err != nil {
		return err
	}

	go mgtr.listenOnPanicAbort()

	// Run on-startup hook:
	if err := mgtr.hooksExecutor.OnStartup(); err != nil {
		return err
	}

	// After this point, we'll need to teardown anything that's been started
	// so we don't leave things hanging around
	defer mgtr.teardown()

	if err := mgtr.initiateInspector(); err != nil {
		return err
	}
	if err := mgtr.checkAbort(); err != nil {
		return err
	}
	if err := mgtr.initiateApplier(); err != nil {
		return err
	}
	if err := mgtr.initiateStreaming(); err != nil {
		return err
	}
	if err := mgtr.checkAbort(); err != nil {
		return err
	}

	// TODO(chriskirkland): move this into a well-named function
	// populate the unique key for the migration.  in single-cluster modes where we may be ALTERing the table, we need
	// to validate the migration has a valid unique key to use here... but in move-tables, the source and target tables
	// are identical,s owe just need to grab any valid UNIQUE key constraint.
	mgtr.migrationContext.UniqueKey = mgtr.inspector.selectUniqueKey(mgtr.migrationContext.OriginalTableUniqueKeys)

	// columns are identical on the source and target tables
	mgtr.migrationContext.SharedColumns = mgtr.migrationContext.OriginalTableColumns
	mgtr.migrationContext.MappedSharedColumns = mgtr.migrationContext.OriginalTableColumns

	// this function assumes that the unique key constraint has been set.
	if err := mgtr.applier.prepareQueries(); err != nil {
		return err
	}

	// Validation complete! Run on-validated hook.
	if err := mgtr.hooksExecutor.OnValidated(); err != nil {
		return err
	}

	if err := mgtr.initiateServer(); err != nil {
		return err
	}
	defer mgtr.server.RemoveSocketFile()

	if err := mgtr.countTableRows(); err != nil {
		return err
	}
	if err := mgtr.addDMLEventsListener(); err != nil {
		return err
	}

	if err := mgtr.applier.ReadMigrationRangeValues(mgtr.inspector.db); err != nil {
		return err
	}

	mgtr.initiateThrottler()

	// Run on-before-row-copy hook
	if err := mgtr.hooksExecutor.OnBeforeRowCopy(); err != nil {
		return err
	}
	go func() {
		if err := mgtr.executeWriteFuncs(); err != nil {
			// Send error to PanicAbort to trigger abort
			_ = base.SendWithContext(mgtr.migrationContext.GetContext(), mgtr.migrationContext.PanicAbort, err)
		}
	}()
	go mgtr.iterateChunks()
	mgtr.migrationContext.MarkRowCopyStartTime()
	go mgtr.initiateStatus()

	mgtr.migrationContext.Log.Debugf("Operating until row copy is complete")
	mgtr.consumeRowCopyComplete()
	mgtr.migrationContext.Log.Infof("Row copy complete")
	// Check if row copy was aborted due to error
	if err := mgtr.checkAbort(); err != nil {
		return err
	}
	if err := mgtr.hooksExecutor.OnRowCopyComplete(); err != nil {
		return err
	}

	//TODO: cutover here

	// temporarily use a file on disk to indicate cutover
	if mgtr.migrationContext.MoveTables.TmpCutoverFilename != "" {
		mgtr.migrationContext.Log.Infof("Waiting for cutover signal (%s)...", mgtr.migrationContext.MoveTables.TmpCutoverFilename)

		timeout := time.After(60 * time.Second)
	LOOP:
		for {
			select {
			case <-timeout:
				mgtr.migrationContext.Log.Errorf("Timeout reached waiting for cutover signal (%s)", mgtr.migrationContext.MoveTables.TmpCutoverFilename)
			default:
				// check if cutover file name exists
				if _, err := os.Stat(mgtr.migrationContext.MoveTables.TmpCutoverFilename); err != nil {
					continue
				}
				mgtr.migrationContext.Log.Infof("Cutover signal received (%s)", mgtr.migrationContext.MoveTables.TmpCutoverFilename)

				if err := mgtr.simulateMoveTablesCutover(); err != nil {
					return fmt.Errorf("simulated cutover failed: %w", err)
				}
				mgtr.migrationContext.Log.Info("Simulated cutover complete 🎉")
				break LOOP
			}
		}
	}

	if err := mgtr.finalCleanup(); err != nil {
		return nil
	}
	if err := mgtr.hooksExecutor.OnSuccess(false); err != nil {
		return err
	}
	mgtr.migrationContext.Log.Infof("Done moving tables %v from %s to %s (%s)",
		mgtr.migrationContext.MoveTables.TableNames, sql.EscapeName(mgtr.migrationContext.DatabaseName),
		sql.EscapeName(mgtr.migrationContext.MoveTables.TargetDatabase), mgtr.migrationContext.MoveTables.TargetHost)
	// Final check for abort before declaring success
	if err := mgtr.checkAbort(); err != nil {
		return err
	}
	return nil
}

// TODO(chriskirkland): replace this with a _real_ cutover implementation
func (mgtr *Migrator) simulateMoveTablesCutover() (err error) {
	if !mgtr.migrationContext.IsMoveTablesMode() {
		return errors.New("not in MoveTables mode")
	}

	// manually hack the `mysql-source-primary` connection config based on test bed settings
	// this is just for demo purposes... I'm sorry.
	primaryConnectionConfig := mgtr.inspector.connectionConfig.Duplicate()
	primaryConnectionConfig.Key.Port = 3307

	primaryURI := primaryConnectionConfig.GetDBUri(mgtr.migrationContext.DatabaseName)
	primaryDB, _, err := mysql.GetDB(mgtr.migrationContext.Uuid, primaryURI)
	if err != nil {
		return fmt.Errorf("failed to connect to primary of source cluster: %w", err)
	}

	// rename the original table in the source cluster to prevent further reads/writes; mimics the "full cutover" as describe in
	// https://github.com/github/gh-ost-tablemove-poc/blob/9dc6df75c4c88ff473906a497836c7518f5614ec/design/coop_cutover.md

	database := mgtr.migrationContext.DatabaseName
	oldTable := mgtr.migrationContext.MoveTables.TableNames[0]
	delTable := fmt.Sprintf("_%s_del", oldTable)
	query := fmt.Sprintf("RENAME TABLE %s.%s TO %s.%s", sql.EscapeName(database), sql.EscapeName(oldTable), sql.EscapeName(database), sql.EscapeName(delTable))
	if _, err := primaryDB.Exec(query); err != nil {
		return fmt.Errorf("failed to rename table: %w", err)
	}
	mgtr.migrationContext.Log.Infof("[SIMULATED CUTOVER] Table %s renamed to %s._%s_del", oldTable, database, oldTable)

	return nil
}

