func prepareDatabase(t *testing.T, db *gosql.DB) {
	_, err := db.Exec("RESET MASTER")
	require.NoError(t, err)

	_, err = db.Exec("SET @@GLOBAL.	binlog_transaction_dependency_tracking = WRITESET")
	require.NoError(t, err)

	_, err = db.Exec("CREATE DATABASE test")
	require.NoError(t, err)

