func upDevel(remoteNames []string, packageC chan upgrade, done chan bool) {
	for _, e := range savedInfo {
		if e.needsUpdate() {
			found := false
			for _, r := range remoteNames {
				if r == e.Package {
					found = true
				}
			}
			if found {
				packageC <- upgrade{e.Package, "devel", e.SHA[0:6], "git"}
			} else {
				removeVCSPackage([]string{e.Package})
			}
		}
	}
	done <- true
	return
